(function () {
  'use strict';
  document.addEventListener('DOMContentLoaded', init, {once:true});
  function init() {
    const $ = s => document.querySelector(s);
    const api = window.PrototypeStore;
    const store = new api.Store();
    const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const typeNames=api.TYPES;
    const stages={formal:'正式商户',target:'目标商户',intention:'意向商户'};
    const statuses={pending:'待处理',reviewing:'审核中',rejected:'已驳回',completed:'已完成',cancelled:'已取消'};
    const ongoing=t=>!['completed','cancelled'].includes(t.status);
    const timestamp=t=>t?new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
    const freshFilters=entry=>({entry,q:'',stage:'all',type:'all',status:entry==='tasks'?'unfinished':'all',claim:'all',active:'all',recent:'all',tag:'all',source:'all',visit:'all',visitStart:'',visitEnd:'',urgency:'all',unlocated:false,sort:'updated',distance:null});
    let filters=freshFilters('tasks'), layers={points:true,heat:false,outlets:false,radius:0}, currentId=null, selectedId=null, taskTab='all',historyWindow='90',person=null,bounds=null,viewScope=false,pick=null,pickReturn=null;
    const entryStates={};
    let modalSave=null, modalDirty=false, closeHook=null, toastTimer, currentFiles=[], mapState={kind:'offline',message:'未配置高德 Key'};
    let config={...window.MerchantMapConfig};
    const map=new MerchantMap($('#map-canvas'),{
      onSelect:id=>{if(id==='outlet'||String(id).startsWith('outlet'))return outletCard();selectedId=id;merchantCard(id);render();},
      onBoundsChange:value=>{bounds=value;renderList();},
      onStatus:value=>{mapState=value;$('#map-status').innerHTML='<span>'+esc(value.message)+'</span>';},
      onPick:value=>{pick=value;$('#pick-confirm').hidden=false;toast(value.simulated?'已选位置，请填写实际地址':'已选位置，请确认详细地址');}
    });
    new ResizeObserver(()=>map.resize()).observe($('.map-zone'));
    const toast=message=>{clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3600);};
    const getCurrent=()=>currentId?store.get(currentId):null;
    const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
    const distanceText=m=>{const n=person?api.distance(m,person):null;return n==null?'距离未知':n<1000?Math.round(n)+'m':(n/1000).toFixed(1)+'km';};
    function merchantBadges(m){return badge(stages[m.stage],m.stage==='formal'?'green':m.stage==='intention'?'blue':'amber')+(m.stage==='formal'?badge({active:'活跃',inactive:'非活跃',unknown:'活跃未知'}[m.active],m.active==='active'?'green':''):'')+(m.recentTrade===true?badge('近期交易','blue'):'')+m.tags.map(t=>badge(t)).join('');}
    const eligible=m=>m.tasks.some(t=>['pending','rejected'].includes(t.status));
    const claimLabel=m=>m.claim?(m.claim.owner==='me'?'我已领取':'他人已领取'):(eligible(m)?'待领取':'无需领取');
    function matchedTasks(m){return m.tasks.filter(t=>(filters.type==='all'||t.type===filters.type)&&(filters.status==='all'||filters.status==='unfinished'&&ongoing(t)||t.status===filters.status));}
    function inBounds(m){return api.located(m)&&(!bounds||m.lng>=bounds.west&&m.lng<=bounds.east&&m.lat>=bounds.south&&m.lat<=bounds.north);}
    function getRows(){try{return store.list({...filters,person});}catch(e){toast(e.message);return []}}
    function render(){renderList();map.render(getRows(),{...layers,selectedId,person});$('.miniapp-title').textContent=currentId?'商户详情':filters.entry==='data'?'商户热力图':'任务管理';document.querySelectorAll('[data-action="entry"]').forEach(b=>b.classList.toggle('active',b.dataset.entry===filters.entry));document.querySelectorAll('[data-action="quick"]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filters.claim));const n=Object.entries(filters).filter(([k,v])=>!['entry','q','sort','claim'].includes(k)&&v!==freshFilters(filters.entry)[k]).length;$('#filter-count').textContent=n?'· '+n:'';$('#search-input').value=filters.q;$('#sort-select').value=filters.sort;$('#scope-button').textContent=viewScope?'当前视野':'全部结果';}
    function renderList(){const rows=getRows(),visible=rows.filter(inBounds);$('#merchant-count').textContent=rows.length;$('#task-count').textContent=rows.reduce((n,m)=>n+matchedTasks(m).length,0)+' 项匹配任务';$('#unlocated-button').textContent='未定位 '+rows.filter(m=>!api.located(m)).length;$('#viewport-count').textContent='当前视野 '+visible.length+' 户 · 武林支行';$('#result-caption').textContent=filters.unlocated?'未定位商户':filters.entry==='data'?'商户分布':'任务商户';const list=viewScope?visible:rows;$('#merchant-list').innerHTML=list.length?list.map(m=>`<button class="merchant-card ${selectedId===m.id?'selected':''}" data-action="merchant" data-id="${esc(m.id)}"><div class="card-top"><span class="merchant-avatar ${m.stage}">${esc(m.name.charAt(0))}</span><span class="card-title">${esc(m.name)}</span><span class="card-distance">${api.located(m)?distanceText(m):'未定位'}</span></div><p class="card-address">${esc(m.address)}</p><div class="badges">${merchantBadges(m)}</div><div class="card-foot"><span>${m.tasks.filter(ongoing).length} 项未结束 · ${claimLabel(m)}</span><span class="card-arrow">查看商户 ›</span></div></button>`).join(''):'<div class="empty"><div class="empty-icon">⌕</div><strong>没有匹配的商户</strong>试试调整筛选，或查看全部结果</div>';}
    function modal(title,body,{saveLabel,save,foot='',onClose=null}={}){modalDirty=false;closeHook=onClose;modalSave=save;$('#map-page').inert=true;$('#detail-page').inert=true;$('#map-page').setAttribute('aria-hidden','true');$('#detail-page').setAttribute('aria-hidden','true');$('#overlay').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="modal-close" data-action="close" aria-label="关闭弹层">×</button></div><form id="modal-form" class="modal-body"><div id="form-error" class="form-error" role="alert" hidden></div>${body}</form><div class="modal-footer">${foot}${save?`<button class="primary" type="submit" form="modal-form">${esc(saveLabel||'保存')}</button>`:''}</div></section>`;$('#overlay').hidden=false;$('#modal-form').addEventListener('input',()=>modalDirty=true);$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();if(!modalSave)return;const submit=$('[form="modal-form"]');if(submit)submit.disabled=true;try{await modalSave(new FormData(e.target),e.target);}catch(err){$('#form-error').textContent=err.message;$('#form-error').hidden=false;$('#form-error').scrollIntoView({block:'nearest'});}finally{if(submit)submit.disabled=false;}});}
    function close(force=false){if(!force&&modalDirty&&!confirm('内容尚未保存，确定离开？'))return false;$('#overlay').hidden=true;$('#map-page').inert=false;$('#detail-page').inert=false;$('#map-page').removeAttribute('aria-hidden');$('#detail-page').removeAttribute('aria-hidden');modalDirty=false;modalSave=null;if(closeHook){const h=closeHook;closeHook=null;h();}return true;}
    function finish(message){close(true);render();if(currentId)renderDetail();toast(message);}
    const field=(name,label,value='',extra='')=>`<label class="field"><span class="field-title">${label}</span><input name="${name}" aria-label="${esc(label)}" value="${esc(value)}" ${extra}></label>`;
    const area=(name,label,value='',max=500,required=true)=>`<label class="field"><span class="field-title">${label}</span><textarea name="${name}" aria-label="${esc(label)}" maxlength="${max}" ${required?'required':''}>${esc(value)}</textarea></label>`;
    const select=(name,label,items,value)=>`<label class="field"><span class="field-title">${label}</span><select name="${name}" aria-label="${esc(label)}">${Object.entries(items).map(([k,v])=>`<option value="${esc(k)}" ${String(k)===String(value)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
    const check=(name,label,on=false,value='on')=>`<label class="check-row"><input type="checkbox" name="${name}" value="${esc(value)}" ${on?'checked':''}>${esc(label)}</label>`;
    function filterModal(){modal('筛选商户',`<div class="two-fields">${select('stage','商户阶段',{all:'全部阶段',...stages},filters.stage)}${select('claim','领取范围',{all:'全部',unclaimed:'待领取',mine:'我已领取',others:'他人已领取'},filters.claim)}</div>${select('type','任务类型',{all:'全部任务类型',...typeNames},filters.type)}${select('status','任务状态',{unfinished:'未结束',all:'全部（含历史）',...statuses},filters.status)}<div class="two-fields">${select('active','活跃状态',{all:'不限',active:'活跃',inactive:'非活跃',unknown:'未知'},filters.active)}${select('recent','近7天交易',{all:'不限',yes:'有交易',no:'无交易',unknown:'未知'},filters.recent)}</div>${select('tag','跟进标签',{all:'不限',...Object.fromEntries(api.MANUAL_TAGS.map(t=>[t,t]))},filters.tag)}<div class="two-fields">${select('source','来源',{all:'不限','系统导入':'系统导入','手工录入':'手工录入'},filters.source)}${select('visit','走访情况',{all:'不限',visited:'区间已走访',unvisited:'区间未走访'},filters.visit)}</div><div class="two-fields">${field('visitStart','走访开始日期',filters.visitStart,'type="date"')}${field('visitEnd','走访结束日期',filters.visitEnd,'type="date"')}</div><p class="help">未填日期默认近30天，区间最长366天。</p>${select('urgency','特殊作业',{all:'不限',reclaim:'24小时内即将回收',overdue:'任务已逾期',rejected:'任务已驳回'},filters.urgency)}${select('distance','距我的位置',{all:'不限',1000:'1公里内',3000:'3公里内',5000:'5公里内'},filters.distance??'all')}${check('unlocated','仅看未定位商户',filters.unlocated)}<p class="help">同一任务需同时符合类型与状态。详情不继承任务筛选。</p>`,{saveLabel:'查看结果',save:fd=>{const next={...filters,...Object.fromEntries(fd)};next.unlocated=fd.has('unlocated');next.distance=fd.get('distance')==='all'?null:Number(fd.get('distance'));if(next.distance&&!person)throw Error('请先在地图点击定位，再使用距离筛选');store.list({...next,person});filters=next;viewScope=false;selectedId=null;close(true);render();},foot:'<button class="secondary" type="button" data-action="reset-in-modal">重置</button>'});}
    function merchantCard(id){const m=store.get(id);selectedId=id;const title=m.name;modal(title,`<div class="badges">${merchantBadges(m)}</div><p class="detail-address">${esc(m.address)}<br>${api.located(m)?distanceText(m):'暂无有效定位'} · ${esc(m.org)}</p><div class="info-row"><span>匹配任务 / 全部未结束</span><span>${matchedTasks(m).length} / ${m.tasks.filter(ongoing).length} 项</span></div><div class="badges">${m.tasks.filter(ongoing).map(t=>badge(typeNames[t.type],t.type==='risk'?'red':'')).join('')||badge('暂无未结束任务')}</div><p class="subtle">${claimLabel(m)} · 一个商户一个维护地址</p>`,{foot:`<button class="secondary" data-action="navigate" data-id="${id}">导航到店</button><button class="primary" data-action="detail" data-id="${id}">商户详情</button>`});}
    function showExpandedDetailArchived(id){close(true);currentId=id;taskTab='all';if(location.hash!=='#merchant/'+id)history.pushState({merchant:id},'','#merchant/'+id);$('#map-page').hidden=true;$('#detail-page').hidden=false;renderDetail();const m=getCurrent();const info=$('.merchant-info-card'),wrap=$('.detail-wrap');if(wrap)wrap.classList.add('detail-hero');if(m&&info&&!$('.merchant-primary-actions')){const actions=document.createElement('div');actions.className='detail-actions merchant-primary-actions';actions.innerHTML=!m.claim&&eligible(m)&&m.leadStatus!=='abandoned'?'<button class="primary" data-action="claim">领取商户</button><button class="secondary" data-action="visit">记录走访</button>':'<button class="secondary" data-action="visit">记录走访</button>';info.insertAdjacentElement('afterend',actions);}$('.miniapp-title').textContent='商户详情';}
    function backExpandedDetailArchived(){if(!close())return;currentId=null;$('#detail-page').hidden=true;$('#map-page').hidden=false;history.replaceState(null,'',location.pathname+location.search);render();requestAnimationFrame(()=>map.resize());}
    function renderExpandedDetailArchived(){const m=getCurrent();if(!m)return;const tasks=taskTab==='completed'?store.completedTasks(m.id,historyWindow):m.tasks.filter(t=>taskTab==='all'||t.status===taskTab);const claimed=m.claim?.owner==='me';const deadline=m.claim&&!m.claim.firstActionAt?Math.max(0,Math.ceil((m.claim.deadline-Date.now())/3600000)):null;const pendingCount=m.tasks.filter(t=>t.status==='pending').length,reviewCount=m.tasks.filter(t=>t.status==='reviewing').length,rejectedCount=m.tasks.filter(t=>t.status==='rejected').length,completedCount=m.tasks.filter(t=>t.status==='completed').length;const rejectNotice=m.tasks.find(t=>t.status==='rejected');$('#detail-page').innerHTML=`<header class="detail-header"><button data-action="back" aria-label="返回地图">‹</button><h1>商户任务详情</h1><div class="detail-header-actions"><button aria-label="通知">♧</button><button aria-label="更多">⋮</button></div></header><div class="detail-wrap"><section class="merchant-info-card"><div class="merchant-info-main"><div class="merchant-name-row"><h2>${esc(m.name)}</h2>${badge(stages[m.stage],m.stage==='formal'?'green':m.stage==='intention'?'blue':'amber')}</div><div class="merchant-fields"><div><span class="field-icon">▣</span><span class="field-label">商户号：</span><strong>${esc(m.no)}</strong></div><div><span class="field-icon">♙</span><span class="field-label">负责人：</span><strong>${esc(m.contact||'未维护')}</strong></div><div><span class="field-icon">▯</span><span class="field-label">联系电话：</span><strong>${esc(m.phone||'未维护')}</strong></div><div><span class="field-icon">⌖</span><span class="field-label">距离商户：</span><strong>${api.located(m)?distanceText(m):'未定位'}</strong></div><div class="merchant-address"><span class="field-icon">●</span><span class="field-label">地址：</span><strong>${esc(m.address)}</strong></div></div></div><button class="merchant-nav-button" data-action="navigate" data-id="${m.id}" title="导航到商户"><span>⌖</span><small>导航</small></button></section>${rejectNotice?`<section class="notification-card rejected"><strong>审核驳回通知</strong><span>${esc(typeNames[rejectNotice.type])}任务有驳回，请及时查看。</span></section>`:deadline!==null?`<section class="notification-card"><strong>任务时效通知</strong><span>${claimed?'我已领取':'他人已领取'} · 首次处理剩余 ${deadline} 小时，请及时处理。</span></section>`:''}<section class="segment-shell"><div class="segment-control">${[['all','全部',m.tasks.length],['pending','待处理',pendingCount],['reviewing','审核中',reviewCount],['rejected','已驳回',rejectedCount],['completed','已完成',completedCount]].map(([k,label,count])=>`<button class="segment-btn ${taskTab===k?'active':''}" data-action="task-tab" data-value="${k}">${label}(${count})</button>`).join('')}</div></section><section class="task-list-area"><div class="task-scroll-container">${taskTab==='completed'?'<div class="history-tabs"><button class="chip '+(historyWindow==='90'?'selected':'')+'" data-action="history-window" data-value="90">近90天</button><button class="chip '+(historyWindow==='all'?'selected':'')+'" data-action="history-window" data-value="all">全部历史</button></div>':''}${tasks.map(t=>`<article class="task-item task-card"><div class="task-item-heading"><h3>${esc(typeNames[t.type])}</h3>${badge(statuses[t.status],t.status==='rejected'?'red':t.status==='completed'?'green':'amber')}</div><div class="task-item-body"><div class="task-meta"><div>${t.id} · 截止 ${timestamp(t.dueAt)}</div><div>${t.reviewRequired?'处理后按原任务流程审核':'免审任务，提交后完成'}${t.rejectionReason?'<br>驳回原因：'+esc(t.rejectionReason):''}</div></div><button class="primary task-action" data-action="task" data-task="${t.id}">${['pending','rejected'].includes(t.status)?t.status==='rejected'?'重新提交':'去处理':'查看详情'}</button></div><div class="task-tags">${m.tags.map(tag=>badge(tag)).join('')}</div></article>`).join('')||'<div class="empty">暂无此状态任务</div>'}</div></section><section class="panel merchant-operations"><div class="panel-title"><h3>商户作业</h3></div>${m.leadStatus!=='abandoned'?'<details class="mock-panel"><summary>任务下发</summary><p class="help">下发新任务，已有有效领取人时沿用归属；结束或回收后重新领取。</p><button class="secondary" data-action="issue-task">下发任务</button></details>':''}<div class="action-grid"><button data-action="visit"><span>⌖</span>记录走访</button><button data-action="tags"><span>♧</span>跟进标签</button><button data-action="correct"><span>⌁</span>校正位置</button>${m.stage!=='formal'&&m.leadStatus!=='abandoned'?`<button data-action="intention"><span>◇</span>${m.stage==='target'?'标记意向':'编辑意向'}</button><button data-action="conversion"><span>↗</span>转为正式</button><button data-action="abandon"><span>⊘</span>放弃线索</button>`:''}</div></section><section class="panel"><div class="panel-title"><h3>走访记录</h3><small>${m.visits.length} 次</small></div>${m.visits.slice().reverse().map(v=>`<div class="timeline-item">${esc(v.result)} ${badge(v.verificationStatus==='verified'?'有效打卡':'未核验',v.verificationStatus==='verified'?'green':'amber')}<small>${timestamp(v.at||v.visitedAt)} · ${v.distance==null?'距离未知':Math.round(v.distance)+'米'}</small>${esc(v.note||'')}<div class="proof-images">${(v.photos||[]).filter(p=>p.dataUrl).map(p=>`<img src="${p.dataUrl}" alt="走访照片">`).join('')}</div></div>`).join('')||'<p class="subtle">暂无走访记录。导航和任务提交不会自动生成打卡。</p>'}</section><section class="panel"><div class="panel-title"><h3>操作记录</h3></div>${m.history.slice(-8).reverse().map(h=>`<div class="timeline-item">${esc(h.event)}<small>${timestamp(h.at)}</small>${esc(h.detail?.reason||'')}</div>`).join('')||'<p class="subtle">暂无操作记录</p>'}</section></div>`;}
    function issueTask(){const m=getCurrent();const types=Object.fromEntries(Object.entries(typeNames).filter(([type])=>m.stage==='formal'?type!=='target_visit':type==='target_visit'));modal('下发任务',`${select('type','新增任务类型',types,Object.keys(types)[0])}<p class="help">下发任务后，已有有效领取人继续处理。</p>`,{saveLabel:'确认下发',save:fd=>{const updated=store.issueTask(m.id,{type:fd.get('type')});finish(updated.claim?'任务已新增，沿用当前领取人':'任务已新增，等待重新领取');}});}
    function claim(){const m=getCurrent();modal('领取商户',`<strong>${esc(m.name)}</strong><p class="subtle">领取该商户下可处理的全部任务。72小时内至少成功提交一项任务，到期前24小时提醒。</p>`,{saveLabel:'确认领取',save:()=>{store.claim(m.id,m.version);finish('领取成功 · 72小时内处理至少一项任务');}});}
    function attachField(label='证明材料'){currentFiles=[];return `<label class="field"><span class="field-title">${label}</span><input id="attachment-input" type="file" multiple accept="image/jpeg,image/png,application/pdf"><small>最多选择9份，每份≤10MB。</small><span class="file-list" id="file-list"></span></label>`;}
    function wireFiles(){const input=$('#attachment-input');if(!input)return;input.addEventListener('change',async()=>{try{const files=Array.from(input.files);if(files.length>9)throw Error('最多选择9份附件');if(files.some(f=>f.size>10*1024*1024||!['image/jpeg','image/png','application/pdf'].includes(f.type)))throw Error('支持JPG/PNG/PDF，每份不超过10MB');currentFiles=[];for(const file of files){let dataUrl=null;if(file.type.startsWith('image/')){dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,480/img.width);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.65));};img.src=reader.result;};reader.readAsDataURL(file);});}currentFiles.push({name:file.name,type:file.type,size:file.size,dataUrl});}$('#file-list').textContent=currentFiles.map(f=>f.name).join('、');}catch(e){currentFiles=[];input.value='';$('#file-list').textContent=e.message;}});}
    function taskForm(id){const m=getCurrent(),t=m.tasks.find(t=>t.id===id);if(!['pending','rejected'].includes(t.status)){const submission=t.submissions.at(-1);modal(typeNames[t.type],`<div class="badges">${badge(statuses[t.status],t.status==='completed'?'green':'amber')}</div><p class="subtle">${submission?esc(submission.note):'暂无提交记录'}</p>${submission?`<p class="help">提交于 ${timestamp(submission.at)}</p><div class="proof-images">${(submission.attachments||[]).filter(a=>a.dataUrl).map(a=>`<img src="${a.dataUrl}" alt="任务附件">`).join('')}</div>`:''}${t.status==='reviewing'?`<details class="mock-panel"><summary>原有任务审核结果</summary><p class="help">按现有任务审核流程更新结果。</p><button class="secondary" data-action="review" data-task="${t.id}" data-approved="true">审核通过</button><button class="danger" data-action="review" data-task="${t.id}" data-approved="false">审核驳回</button></details>`:''}`,{foot:'<button class="secondary" data-action="close">关闭</button>'});return;}
      if(m.claim?.owner!=='me'){toast(m.claim?'该商户由他人领取，当前只可查看':'请先领取商户，再处理任务');return;}
      const draftKey='youfu.task.draft.'+t.id;let draft={};try{draft=JSON.parse(sessionStorage.getItem(draftKey)||'{}');}catch(_){}
      let fields='';if(t.type==='channel_switch')fields=select('channel','备用通道',{demo_a:'备用通道A',demo_b:'备用通道B'},draft.channel||'demo_a')+check('wechatConfirmed','已核对微信认证结果',draft.wechatConfirmed==='on')+check('alipayConfirmed','已核对支付宝认证结果',draft.alipayConfirmed==='on');
      if(t.type==='suspense')fields=select('method','处理方式',{refund:'更换信息后处理挂账',change:'变更结算账户'},draft.method)+field('accountName','新结算户名',draft.accountName,'required maxlength="50"')+field('idNo','新结算证件号',draft.idNo,'required maxlength="18"')+field('accountNo','新银行卡号',draft.accountNo,'required inputmode="numeric" maxlength="30"')+field('bank','开户行',draft.bank,'required')+field('branch','开户支行',draft.branch,'required');
      if(t.type==='supplement')fields+='<div class="notice green">本次任务要求：营业执照、法人身份证及银行卡资料。请按要求上传材料。</div>';
      if(t.type==='risk')fields+='<div class="notice">核实异常情况并补充说明及证明材料。此处提交不等于风控裁决完成。</div>';
      modal(typeNames[t.type],`<p class="subtle">${esc(m.name)} · ${t.reviewRequired?'提交后按原流程审核':'免审完成'}</p>${fields}${area('note','处理说明',draft.note||'',500)}${attachField(t.type==='suspense'?'银行卡、证件正反面及其他材料':'相关证明材料')}`,{saveLabel:t.status==='rejected'?'重新提交':'提交任务',save:fd=>{const f=Object.fromEntries(fd);f.wechatConfirmed=fd.has('wechatConfirmed');f.alipayConfirmed=fd.has('alipayConfirmed');if(t.type==='supplement'&&currentFiles.length<3)throw Error('请上传营业执照、法人证件和银行卡三项材料');if(t.type==='suspense'&&currentFiles.length<3)throw Error('请上传银行卡及证件正反面三项材料');store.submitTask(m.id,t.id,{note:f.note,fields:f,attachments:currentFiles},{idempotencyKey:'task-'+t.id+'-'+m.version});sessionStorage.setItem(draftKey,'{}');finish(t.reviewRequired?'提交成功 · 等待原流程审核':'任务已完成');},foot:'<button type="button" class="secondary" data-action="save-draft" data-task="'+t.id+'">保存草稿</button>'});wireFiles();}
    function visitForm(){const m=getCurrent();modal('记录走访',`<div class="location-preview"><strong>${esc(m.name)}</strong>${person?'人员位置已获取 · '+distanceText(m):'尚未获取人员位置'}<br>有效打卡需100米内、定位60秒内、精度≤50米；需要有效定位才能计入有效到店。</div><button type="button" class="secondary full-width" data-action="locate-visit">更新人员位置</button>${select('result','走访结果',{沟通完成:'沟通完成',未营业:'未营业',未找到:'未找到',其他:'其他'},'沟通完成')}${area('note','走访备注','',100,false)}${field('supplementReason','未核验 / 补录原因','','placeholder="无有效定位时必填" maxlength="200"')}${m.tasks.length?'<div class="field"><span class="field-title">关联任务（选填）</span>'+m.tasks.map(t=>check('linkedTaskIds',typeNames[t.type]+' · '+t.id,false,t.id)).join('')+'</div>':''}${attachField('走访照片（选填）')}<p class="help">记录走访不会自动完成该商户全部任务。</p>`,{saveLabel:'保存走访',save:fd=>{const result=store.visit(m.id,{result:fd.get('result'),note:fd.get('note'),supplementReason:fd.get('supplementReason'),location:person,linkedTaskIds:fd.getAll('linkedTaskIds'),photos:currentFiles.filter(f=>f.type.startsWith('image/'))},{idempotencyKey:'visit-'+Date.now()});finish(result.verificationStatus==='verified'?'有效到店打卡已记录':'已保存未核验走访，不计有效到店');}});wireFiles();}
    function tags(){const m=getCurrent();modal('跟进标签',`<p class="help">活跃、交易和任务标签来自业务状态，不可手工修改。</p>${api.MANUAL_TAGS.map(t=>check('tags',t,m.tags.includes(t),t)).join('')}`,{saveLabel:'保存标签',save:fd=>{store.updateTags(m.id,fd.getAll('tags'),m.version);finish('跟进标签已更新');}});}
    function positionForm(id=null,value=null){const m=id?store.get(id):null;const values=value||m||{};modal(m?'校正商户位置':'新增目标商户',`${m?`<div class="location-preview"><strong>当前维护地址</strong>${esc(m.address)}<br>${api.located(m)?m.lng.toFixed(5)+', '+m.lat.toFixed(5):'无有效坐标'}</div>`:field('name','商户名称',values.name,'required maxlength="100"')}${field('address','商户维护地址',values.address,'required maxlength="200" placeholder="请填写到店详细地址"')}<div class="two-fields">${field('lng','经度',values.lng??'','type="number" step="any" min="-180" max="180"')}${field('lat','纬度',values.lat??'','type="number" step="any" min="-90" max="90"')}</div><button type="button" class="secondary full-width" data-action="pick-position" data-id="${m?.id||''}">地图选点</button><p class="help">${values.simulated?'已选择地图位置。':'使用GCJ-02坐标。新增时可暂缺位置，之后在未定位清单补充。'}</p>${m?area('reason','校正原因',values.reason||'',200):field('contact','联系人',values.contact,'maxlength="50"')+field('phone','联系电话',values.phone,'type="tel" maxlength="32"')}<p class="help">${m?'确认后校验并保存，不新增审批。只更新商户走访地址，不变更机构和结算资料。':'创建目标商户后进入正常作业流程。'}</p>`,{saveLabel:m?'确认校正':'创建目标商户',save:fd=>{const v=Object.fromEntries(fd);if(m){if(v.lng===''||v.lat==='')throw Error('校正时必须填写完整坐标');store.correctPosition(m.id,{lng:Number(v.lng),lat:Number(v.lat),address:v.address,reason:v.reason},m.version);finish('商户位置已更新，无需审批');}else{if(v.phone&&!/^\+?[\d ()-]{7,32}$/.test(v.phone))throw Error('联系电话格式不正确');const existing=store.exportState().merchants.filter(x=>x.name===v.name||v.phone&&x.phone===v.phone);if(existing.length&&!confirm('已有同名或同电话商户，请确认是不同商户后继续。'))return;const created=store.create(v);close(true);render();showDetail(created.id);toast('目标商户已创建');}}});}
    function intention(){const m=getCurrent();if(m.leadStatus==='abandoned')return toast('已放弃线索不能继续操作');modal(m.stage==='target'?'标记意向':'编辑意向',`${field('contact','联系人',m.contact,'required maxlength="50"')}${field('phone','联系电话',m.phone,'required type="tel" maxlength="32"')}${area('note','意向说明','',500,false)}<p class="help">保留当前商户标识和来源；标记意向不等于正式进件成功。</p>`,{saveLabel:'保存意向',save:fd=>{store.markIntention(m.id,Object.fromEntries(fd));finish('已保存意向信息');}});}
    function conversion(){const m=getCurrent();if(m.stage!=='intention'){toast('请先标记意向，再发起进件');return;}const processing=m.conversion?.status==='processing';modal('转为正式商户',`<div class="location-preview"><strong>${esc(m.name)}</strong>${esc(m.contact)} · ${esc(m.address)}</div><p class="subtle">${processing?'进件处理中，商户仍为意向。通过回执更新状态。':'发起进件或绑定商户号，按进件状态推进商户阶段。'}</p>${m.conversion?.status==='failed'?'<div class="notice red">上次失败：'+esc(m.conversion.reason)+'</div>':''}${processing?field('no','回执中的正式商户号','DEMO'+Date.now().toString().slice(-10),'required pattern="[A-Za-z0-9_-]{5,32}"'):'<p class="help">渠道：业务进件通道；已预填商户名、联系人和地址。</p>'}`,{saveLabel:processing?'接收成功回执':'发起进件',save:fd=>{if(processing){store.resolveConversion(m.id,{success:true,no:fd.get('no'),name:m.name});finish('成功回执已接收 · 商户转为正式，仍只计一户');}else{store.beginConversion(m.id);close(true);renderDetail();conversion();}},foot:processing?'<button type="button" class="secondary" data-action="conversion-fail">记录失败</button>':'<button type="button" class="secondary" data-action="bind">绑定正式号</button>'});}
    function bind(){const m=getCurrent();modal('绑定正式商户',`<p class="help">请核对商户身份后绑定，不能仅凭地址合并。</p>${field('no','正式商户号','','required pattern="[A-Za-z0-9_-]{5,32}"')}${check('identity','已核对为当前商户')}`,{saveLabel:'确认绑定',save:fd=>{if(!fd.has('identity'))throw Error('请先核对商户身份');store.convert(m.id,{no:fd.get('no'),name:m.name});finish('已完成正式商户绑定');}});}
    function abandon(){const m=getCurrent();modal('放弃线索',`<p class="subtle">${esc(m.name)} 将移出待拓展视图。保留原记录，无独立审批；该线索未结束的拓展任务结束跟进。</p>${area('reason','放弃原因','',200)}`,{saveLabel:'确认放弃',save:fd=>{store.abandon(m.id,fd.get('reason'));finish('线索已放弃，历史记录保留');}});}
    function navigate(id){const m=store.get(id);const valid=api.located(m);const route=valid?'https://uri.amap.com/navigation?to='+encodeURIComponent(m.lng+','+m.lat+','+m.name)+'&mode=walk&callnative=1&coordinate=gaode&src=youfu-prototype':'https://uri.amap.com/search?keyword='+encodeURIComponent(m.address)+'&city=杭州';modal('导航到店',`<div class="location-preview"><strong>${esc(m.name)}</strong>${esc(m.address)}</div><p class="subtle">${valid?'目的地为商户当前维护位置。地图位置以当前维护地址为准。':'商户尚未定位，只能按文字地址搜索，不保证精确目的地。'}<br>打开外部地图不等于到店或完成任务。</p><a class="nav-link primary" href="${esc(route)}" target="_blank" rel="noopener" data-action="navigation-start">打开高德路线</a><p class="help">微信内置浏览器可能无法唤起App，可复制地址到地图中搜索。</p>`,{foot:`<button class="secondary" data-action="copy-address" data-id="${m.id}">复制地址</button><button class="secondary" data-action="close">关闭</button>`});}
    function locate(){return new Promise(resolve=>{if(!navigator.geolocation){toast('当前浏览器不支持定位，仍可按区域查看');resolve(false);return;}toast('正在获取人员位置…');navigator.geolocation.getCurrentPosition(async pos=>{try{let lng=pos.coords.longitude,lat=pos.coords.latitude;const convert=await new Promise((res,rej)=>{if(!window.AMap?.convertFrom){rej(Error('坐标转换服务尚未就绪，请配置高德后重试'));return;}AMap.convertFrom([lng,lat],'gps',(status,data)=>status==='complete'&&data.locations?.[0]?res(data.locations[0]):rej(Error('定位坐标转换失败')));});person={lng:convert.lng??convert.getLng(),lat:convert.lat??convert.getLat(),accuracy:pos.coords.accuracy,capturedAt:pos.timestamp,simulated:false};map.focus(person.lng,person.lat);render();toast('人员位置已更新，商户地址未改变');resolve(true);}catch(e){toast(e.message);resolve(false);}},error=>{toast(error.code===1?'定位权限未授权，可继续按业务区域查看':'定位失败或超时，请稍后重试');resolve(false);},{enableHighAccuracy:true,timeout:10000,maximumAge:0});});}
    function layerModal(){modal('地图图层',`<label class="layer-row"><span><strong>商户点位</strong><small>按商户去重，点选查看详情</small></span><input class="switch" name="points" type="checkbox" ${layers.points?'checked':''}></label><label class="layer-row"><span><strong>商户热力</strong><small>每户权重1，不按任务条数累加</small></span><input class="switch" name="heat" type="checkbox" ${layers.heat?'checked':''}></label><label class="layer-row"><span><strong>网点位置</strong><small>武林支行 · 网点</small></span><input class="switch" name="outlets" type="checkbox" ${layers.outlets?'checked':''}></label>${select('radius','网点辐射圈',{0:'不显示',500:'500米',1000:'1000米',2000:'2000米'},layers.radius)}<p class="help">圈层仅表示距离，不改变商户归属或权限。关闭网点时同时隐藏圈层。</p>`,{saveLabel:'应用图层',save:fd=>{layers={points:fd.has('points'),heat:fd.has('heat'),outlets:fd.has('outlets'),radius:Number(fd.get('radius'))};close(true);render();}});}
    function outletCard(){const rows=getRows(),radius=layers.radius||500,inside=rows.filter(m=>api.located(m)&&api.distance(m,{lng:120.1551,lat:30.2741})<=radius);modal('武林支行',`<p class="subtle">${radius}米辐射范围，不代表责任区或商户归属。</p><div class="info-row"><span>圈内匹配商户</span><span>${inside.length} 户</span></div><div class="info-row"><span>未结束任务</span><span>${inside.reduce((n,m)=>n+m.tasks.filter(ongoing).length,0)} 项</span></div><a class="nav-link primary" target="_blank" rel="noopener" href="https://uri.amap.com/navigation?to=120.1551,30.2741,网点&mode=walk&coordinate=gaode">打开网点路线</a>`,{foot:'<button class="secondary" data-action="close">关闭</button>'});}
    function settings(){modal('地图设置',`<p class="subtle">${esc(mapState.message)}<br>高德 JS API 2.0 + Loca 2.0。配置仅保存在当前浏览器会话。</p>${field('key','Web JS API Key',config.key,'autocomplete="off" spellcheck="false"')}${field('securityJsCode','安全密钥',config.securityJsCode,'type="password" autocomplete="off"')}${field('serviceHost','安全代理地址（可选）',config.serviceHost,'placeholder="https://你的域名/_AMapService"')}<p class="help">配置代理时优先使用代理地址；定位需 HTTPS 或 localhost。请将域名加入 Key 白名单。</p><div class="mock-panel"><strong class="subtle">操作指南</strong><p class="help">选择商户 → 查看详情 → 领取 → 处理任务。地图选点用于维护商户地址，人员定位用于走访校验。</p></div>`,{saveLabel:'保存并连接',save:async fd=>{const next=Object.fromEntries(fd);if(next.serviceHost&&!/^https?:\/\//.test(next.serviceHost))throw Error('代理地址需以https://或http://开头');config=next;sessionStorage.setItem('youfu.amap.config',JSON.stringify(config));close(true);await map.init(config);render();toast(map.mode==='amap'?'地图已连接':'地图连接失败，请检查配置');}});}
    async function action(button,event){const a=button.dataset.action,id=button.dataset.id;switch(a){case 'settings':settings();break;case 'region-button':case 'region':modal('业务区域','<p class="subtle">当前业务范围为杭州 · 武林支行，地图移动不扩大数据权限。</p>',{foot:'<button class="primary" data-action="region-reset">回到业务区域</button>'});break;case 'region-reset':map.focus(120.1633,30.2735);close(true);break;case 'filters':filterModal();break;case 'quick':filters.claim=button.dataset.filter;render();break;case 'reset-in-modal':filters=freshFilters(filters.entry);filterModal();render();break;case 'reset-filters':filters=freshFilters(filters.entry);viewScope=false;render();break;case 'unlocated':filters.unlocated=!filters.unlocated;viewScope=false;render();break;case 'view-scope':viewScope=!viewScope;render();break;case 'expand':$('#result-sheet').classList.toggle('expanded');setTimeout(()=>map.resize(),220);break;case 'merchant':selectedId=id;showDetail(id);break;case 'detail':showDetail(id);break;case 'back':backToMap();break;case 'history-window':historyWindow=button.dataset.value;renderDetail();break;case 'task-tab':taskTab=button.dataset.value;renderDetail();break;case 'task':taskForm(button.dataset.task);break;case 'issue-task':issueTask();break;case 'claim':claim();break;case 'visit':visitForm();break;case 'tags':tags();break;case 'correct':positionForm(currentId);break;case 'create':positionForm();break;case 'intention':intention();break;case 'abandon':abandon();break;case 'conversion':conversion();break;case 'bind':bind();break;case 'conversion-fail':store.resolveConversion(currentId,{success:false,reason:'资料不完整，请补齐后重试'});close(true);renderDetail();conversion();break;case 'navigate':navigate(id||currentId);break;case 'copy-address':try{await navigator.clipboard.writeText(store.get(id).address);toast('地址已复制');}catch(_){toast('复制失败，请手动选择地址复制');}break;case 'navigation-start':toast('已发起外部导航，未记录到店');break;case 'layers':layerModal();break;case 'locate':await locate();break;case 'locate-visit':if(await locate()){const preview=$('.modal .location-preview');if(preview)preview.innerHTML='<strong>'+esc(getCurrent().name)+'</strong>人员位置已更新 · '+distanceText(getCurrent())+'<br>精度 '+Math.round(person.accuracy)+'米；保存时按采集时间校验。';}break;case 'close':close();break;case 'save-draft':{const f=Object.fromEntries(new FormData($('#modal-form')));sessionStorage.setItem('youfu.task.draft.'+button.dataset.task,JSON.stringify(f));modalDirty=false;toast('草稿已保存，附件请提交时重新选择');break;}case 'review':{const approved=button.dataset.approved==='true';store.reviewTask(currentId,button.dataset.task,{approved,reason:approved?'':'请补充核实过程及相关材料'});finish(approved?'原流程审核已通过':'原流程审核已驳回');break;}case 'pick-position':{const values=Object.fromEntries(new FormData($('#modal-form')));pickReturn={id:id||null,values,currentId};close(true);$('#detail-page').hidden=true;$('#map-page').hidden=false;map.setPickMode(true);map.resize();$('#pick-cancel').hidden=false;pick=null;$('#pick-confirm').hidden=true;toast('点击地图选择位置，或取消选点');break;}case 'legend':modal('地图图例',`<div class="legend-row"><i class="legend-dot"></i>正式商户 · 活跃绿色 / 非活跃灰色</div><div class="legend-row"><i class="legend-dot target"></i>目标商户</div><div class="legend-row"><i class="legend-dot intention"></i>意向商户</div><p class="subtle">任务徽标：风控、切换等，可同时存在。徽标只表示任务，不代表商户已被判定风险。聚合数字代表商户数。</p><div class="heat-ramp"></div><p class="subtle">低密度 → 高密度 · 按筛选后商户去重计数<br>活跃：近30天有效支付；近期交易：近7天。当前业务口径。</p>`,{foot:'<button class="secondary" data-action="close">知道了</button>'});break;case 'entry':{const next=button.dataset.entry;if(next===filters.entry)return;entryStates[filters.entry]={filters:{...filters},layers:{...layers}};const saved=entryStates[next];filters=saved?.filters||freshFilters(next);layers=saved?.layers||{points:next==='tasks',heat:next==='data',outlets:false,radius:0};selectedId=null;viewScope=false;render();break;}}}
    if(false) new MutationObserver(()=>{document.querySelectorAll('#detail-page .task-item-heading').forEach(node=>node.classList.add('task-title'));document.querySelectorAll('#detail-page .merchant-address').forEach(node=>node.classList.add('detail-address'));const headerBack=$('#detail-page .detail-header>button');if(headerBack&&(headerBack.textContent!=='‹ 返回地图'||headerBack.getAttribute('aria-label')!=='‹ 返回地图')){headerBack.textContent='‹ 返回地图';headerBack.setAttribute('aria-label','‹ 返回地图');}const wrap=$('#detail-page .detail-wrap'),m=getCurrent();document.querySelectorAll('#detail-page .merchant-address').forEach(node=>{if(!node.querySelector('.position-status')){const status=document.createElement('span');status.className='position-status';status.textContent=m&&api.located(m)?' · 位置已维护':' · 请先维护商户位置';node.appendChild(status);}});if(wrap&&m?.leadStatus==='abandoned'&&!wrap.querySelector('.abandoned-notice')){const note=document.createElement('div');note.className='notification-card rejected abandoned-notice';note.innerHTML='<strong>线索已放弃</strong><span>该线索已放弃，保留历史记录。</span>';wrap.prepend(note);}const primary=$('#detail-page .merchant-primary-actions');if(primary&&!primary.querySelector('[data-action="navigate"]')){const nav=document.createElement('button');nav.className='secondary';nav.dataset.action='navigate';nav.textContent='↗ 导航到店';nav.dataset.id=currentId;primary.prepend(nav);}}).observe($('#detail-page'),{childList:true,subtree:true});
    /* 详情页回归旧原型：只保留商户核心信息、状态页签和任务卡。 */
    function renderDetail(){
      const m=getCurrent();if(!m)return;
      const statusNames={pending:'待处理',reviewing:'审核中',rejected:'已驳回',completed:'已完成'};
      const typeNamesOld={supplement:'补充商户资料',channel_switch:'切换备用通道',maintenance:'走访维护商户',risk:'风控任务',suspense:'挂帐任务',target_visit:'目标商户走访'};
      const tasks=taskTab==='completed'?store.completedTasks(m.id,historyWindow):m.tasks.filter(t=>t.status===taskTab);
      const row=(label,value,shape)=>'<div class="original-field"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><'+shape+'/></svg><span class="original-label">'+label+'：</span><span class="original-value">'+esc(value)+'</span></div>';
      const deadline=m.claim&&!m.claim.firstActionAt?Math.max(0,Math.ceil((m.claim.deadline-Date.now())/3600000)):null;
      const rejected=m.tasks.filter(t=>t.status==='rejected');
      const notice=m.leadStatus==='abandoned'?'<div class="original-notice rejected"><strong>线索已放弃</strong></div>':rejected.length?'<div class="original-notice rejected"><strong>审核驳回通知</strong><div>有 '+rejected.length+' 项任务被驳回，请及时查看。</div></div>':deadline!==null?'<div class="original-notice"><strong>任务时效通知</strong><div>72小时内至少提交一项任务'+(deadline<=24?'，剩余 '+deadline+' 小时':'')+'。</div></div>':'';
      const tabs=Object.entries(statusNames).map(([key,label])=>'<button role="tab" aria-selected="'+(taskTab===key)+'" class="'+(taskTab===key?'active':'')+'" data-action="task-tab" data-value="'+key+'">'+label+'<span>('+m.tasks.filter(t=>t.status===key).length+')</span></button>').join('');
      const cards=tasks.map(t=>'<article class="original-task"><h3 class="original-task-title">'+esc(typeNamesOld[t.type]||typeNames[t.type])+'</h3><div class="original-task-body"><div class="original-task-fields"><div><span>处理人：</span>'+esc(m.claim?.owner==='me'?'我':m.claim?'其他客户经理':'未领取')+'</div><div><span>截止时间：</span>'+timestamp(t.dueAt)+'</div>'+(t.rejectionReason?'<div class="original-reason"><span>驳回原因：</span>'+esc(t.rejectionReason)+'</div>':'')+'</div><button class="primary" data-action="task" data-task="'+esc(t.id)+'">'+(t.status==='rejected'?'重新提交':t.status==='pending'?'去处理':'查看详情')+'</button></div></article>').join('')||'<div class="empty">暂无'+statusNames[taskTab]+'任务</div>';
      $('#detail-page').innerHTML='<div class="original-detail"><section class="original-merchant"><div class="original-name"><h2>'+esc(m.name)+'</h2>'+badge(stages[m.stage],m.stage==='formal'?'green':'amber')+'</div><div class="original-merchant-body"><div class="original-fields">'+row('商户号',m.no||'未分配','rect x="3" y="5" width="18" height="14" rx="2"')+row('负责人',m.contact||'未维护','circle cx="12" cy="8" r="4"')+row('联系电话',m.phone||'未维护','rect x="7" y="3" width="10" height="18" rx="2"')+row('距离商户',api.located(m)?distanceText(m):'未定位','circle cx="12" cy="12" r="7"')+row('地址',m.address,'path d="M12 21S5 14 5 9a7 7 0 0114 0c0 5-7 12-7 12Z"')+'</div><button class="original-nav" data-action="navigate" data-id="'+esc(m.id)+'" aria-label="导航到商户"><span style="font-size:28px">⌖</span><span>导航</span></button></div></section>'+notice+(!m.claim&&eligible(m)&&m.leadStatus!=='abandoned'?'<div class="original-claim"><button class="primary" data-action="claim">领取商户</button></div>':'')+'<div class="original-tabs" role="tablist" aria-label="任务状态">'+tabs+'</div>'+(taskTab==='completed'?'<div class="original-history"><button class="chip '+(historyWindow==='90'?'selected':'')+'" data-action="history-window" data-value="90">近90天</button><button class="chip '+(historyWindow==='all'?'selected':'')+'" data-action="history-window" data-value="all">全部历史</button></div>':'')+'<div class="original-task-list">'+cards+'</div></div>';
      $('.miniapp-title').textContent='商户任务详情';document.title='商户任务详情 · 邮付管家';
      let back=$('#detail-shell-back');if(!back){back=document.createElement('button');back.id='detail-shell-back';back.className='miniapp-back';back.setAttribute('aria-label','返回地图');back.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 19l-7-7 7-7"/></svg>';back.addEventListener('click',backToMap);document.querySelector('.miniapp-nav-bar')?.prepend(back);}back.setAttribute('aria-label','返回地图');back.hidden=false;
    }
     function showDetail(id){
       // 地图只负责选中商户，详情统一复用原移动端页面，避免复制一套不一致的详情 UI。
       window.location.href='../移动端/商户任务详情页.html?id='+encodeURIComponent(id);
     }
    function backToMap(){if(!close())return;currentId=null;$('#detail-page').hidden=true;$('#map-page').hidden=false;const back=$('#detail-shell-back');if(back)back.hidden=true;history.replaceState(null,'',location.pathname+location.search);document.title='任务地图 · 邮付管家';render();requestAnimationFrame(()=>map.resize());}
    $('#app').addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button)Promise.resolve(action(button,e)).catch(err=>toast(err.message));});
    $('#region-button').addEventListener('click',()=>action({dataset:{action:'region'}}));
    $('#search-input').addEventListener('input',e=>{filters.q=e.target.value;renderList();map.render(getRows(),{...layers,selectedId,person});});
    $('#sort-select').addEventListener('change',e=>{if(e.target.value==='distance'&&!person){toast('请先获取人员位置');e.target.value=filters.sort;return;}filters.sort=e.target.value;render();});
    $('#pick-confirm').addEventListener('click',()=>{if(!pick||!pickReturn)return;map.setPickMode(false);$('#pick-confirm').hidden=true;const ctx=pickReturn;pickReturn=null;$('#pick-cancel').hidden=true;if(ctx.currentId){currentId=ctx.currentId;$('#map-page').hidden=true;$('#detail-page').hidden=false;}positionForm(ctx.id,{...ctx.values,lng:pick.lng,lat:pick.lat,address:pick.address||ctx.values.address,simulated:pick.simulated});});
    $('#pick-cancel').addEventListener('click',()=>{if(!pickReturn)return;const ctx=pickReturn;pickReturn=null;map.setPickMode(false);$('#pick-confirm').hidden=true;$('#pick-cancel').hidden=true;if(ctx.currentId){currentId=ctx.currentId;$('#map-page').hidden=true;$('#detail-page').hidden=false;}positionForm(ctx.id,ctx.values);});
    window.addEventListener('popstate',()=>{if(pickReturn){map.setPickMode(false);pickReturn=null;$('#pick-confirm').hidden=true;}if(location.hash.startsWith('#merchant/'))showDetail(decodeURIComponent(location.hash.slice(10)));else backToMap();});
    window.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape')close();if(e.key==='Tab'){const items=Array.from($('#overlay').querySelectorAll('button,input,select,textarea,a[href]')).filter(n=>!n.disabled&&n.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
    window.addEventListener('storage',e=>{if(e.key===api.STORAGE_KEY){render();if(currentId)renderDetail();toast('数据已更新');}});
    if(location.hash.startsWith('#merchant/')){try{showDetail(decodeURIComponent(location.hash.slice(10)));}catch(_){backToMap();}}
    map.init(config).then(()=>render());
    render();
  }
})();
